TITLES={'D1.1':'DNA replication','D1.2':'Protein synthesis','D1.3':'Mutation and gene editing','D2.1':'Cell and nuclear division','D2.2':'Gene expression','D2.3':'Water potential','D3.1':'Reproduction','D3.2':'Inheritance','D3.3':'Homeostasis','D4.1':'Natural selection','D4.2':'Stability and change','D4.3':'Climate change'}
INK='#172b4d';BLUE='#176089';ORANGE='#b56520'
def txt(x,y,s,size=16,anchor='middle'):
    lines=str(s).split('\n')
    return f'<text x="{x:g}" y="{y:g}" font-family="Arial,sans-serif" font-size="{size}" text-anchor="{anchor}" fill="{INK}">'+''.join(f'<tspan x="{x:g}" dy="{0 if i==0 else size*1.2:g}">{escape(t)}</tspan>' for i,t in enumerate(lines))+'</text>'
def line(x,y,u,v,color=INK,w=2,dash=False):return f'<line x1="{x:g}" y1="{y:g}" x2="{u:g}" y2="{v:g}" stroke="{color}" stroke-width="{w}"'+(' stroke-dasharray="6 4"' if dash else '')+'/>'
def arrow(x,y,u,v,label='',color=INK):
    dx=u-x;dy=v-y;norm=math.hypot(dx,dy);a=dx/norm;b=dy/norm
    return line(x,y,u,v,color)+line(u,v,u-10*a+5*b,v-10*b-5*a,color)+line(u,v,u-10*a-5*b,v-10*b+5*a,color)+(txt((x+u)/2,(y+v)/2-12,label,14) if label else '')
def box(x,y,w,h,label,fill='#fff'):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="5" fill="{fill}" stroke="{INK}" stroke-width="1.8"/>'+txt(x+w/2,y+h/2-7*(label.count('\n')),label,16)
def circle(x,y,r,label='',fill='#fff'):
    return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}" stroke="{INK}" stroke-width="1.8"/>'+(txt(x,y+5,label,16) if label else '')
def svg(body,title,w=780,h=420):
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img"><title>{escape(title)}</title><rect width="{w}" height="{h}" fill="white"/>'+txt(w/2,28,title,18)+body+'</svg>'
def chart(series,xlab,ylab,title,xrange=None,yrange=None,points=True):
    xs=[x for _,pts in series for x,y in pts];ys=[y for _,pts in series for x,y in pts]
    xa,xb=xrange or (min(xs),max(xs));ya,yb=yrange or (min(0,min(ys)),max(ys)*1.16 or 1)
    X=lambda x:90+590*(x-xa)/(xb-xa or 1);Y=lambda y:315-215*(y-ya)/(yb-ya or 1)
    b=line(90,90,90,315)+line(90,315,695,315)+txt(390,402,xlab,16)+txt(90,64,ylab,15,'start')
    for i in range(6):
        x=xa+(xb-xa)*i/5;y=ya+(yb-ya)*i/5
        b+=txt(X(x),342,f'{x:.3g}',13)+txt(78,Y(y)+4,f'{y:.3g}',13,'end')
    for k,(name,pts) in enumerate(series):
        col=[BLUE,ORANGE,INK,'#56813f'][k%4]
        b+='<polyline points="'+' '.join(f'{X(x):.2f},{Y(y):.2f}' for x,y in pts)+f'" fill="none" stroke="{col}" stroke-width="2.5"'+(' stroke-dasharray="6 4"' if k%2 else '')+'/>'
        if points:
            for x,y in pts:b+=f'<circle cx="{X(x):.2f}" cy="{Y(y):.2f}" r="4" fill="{col}"/>'
        b+=line(120+k*170,77,145+k*170,77,col,2.5,k%2==1)+txt(151+k*170,82,name,13,'start')
    return svg(b,title)
def bars(labels,values,ylab,title,errors=None):
    mx=max(v+(errors[i] if errors else 0) for i,v in enumerate(values))*1.2
    b=line(85,70,85,305)+line(85,305,710,305)+txt(85,57,ylab,15,'start')
    for j in range(5):b+=txt(73,309-220*j/4,f'{mx*j/4:.3g}',13,'end')
    for i,(lab,v) in enumerate(zip(labels,values)):
        x=135+i*520/max(1,len(values)-1);y=305-220*v/mx
        b+=f'<rect x="{x-24}" y="{y}" width="48" height="{305-y}" fill="{BLUE if i%2==0 else ORANGE}"/>'+txt(x,y-12,f'{v:g}',14)+txt(x,335,'\n'.join(textwrap.wrap(lab,17)),14)
        if errors:
            dy=220*errors[i]/mx;b+=line(x,y-dy,x,y+dy)+line(x-8,y-dy,x+8,y-dy)+line(x-8,y+dy,x+8,y+dy)
    return svg(b,title)
def gel(lanes,title):
    b=arrow(45,100,45,310,'')+txt(50,360,'Migration\ndirection',14)
    for i,(name,bands) in enumerate(lanes):
        x=140+i*160;b+=txt(x,70,name,16)+f'<rect x="{x-45}" y="85" width="90" height="235" fill="#eef3f8" stroke="{INK}"/>'+line(x-23,100,x+23,100,INK,4)
        for y in bands:b+=line(x-25,y,x+25,y,BLUE,6)
    b+=txt(400,380,'Constructed band positions; wells at top. No fragment-size calibration.',14)
    return svg(b,title)
def density(rows):
    b=arrow(680,110,680,330,'')+txt(680,370,'Increasing\ndensity',14)
    for i,(name,bands) in enumerate(rows):
        x=115+i*170;b+=txt(x,70,name,16)+f'<rect x="{x-38}" y="95" width="76" height="230" rx="10" fill="#eef3f8" stroke="{INK}"/>'
        for y,lab in bands:b+=line(x-30,y,x+30,y,BLUE,10)+txt(x,y-12,lab,13)
    return svg(b,'Constructed DNA-density results; band widths do not encode amounts')
def stack(*figures):
    body='';offset=0
    for f in figures:
        height=float(re.search(r'viewBox="0 0 780 ([\d.]+)"',f)[1])
        inner=f[f.index('>')+1:f.rindex('</svg>')]
        body+=f'<g transform="translate(0,{offset:g})">{inner}</g>';offset+=height
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 780 {offset:g}" role="img"><title>Constructed multi-panel evidence</title>{body}</svg>'
def M(t):return ('M1',t)
def A(t):return ('A1',t)
def R(t):return ('R1',t)
def P(prompt,*steps):return (prompt,list(steps))
def add(code,title,stem,figure,parts,numerics,reason):
    num=701+len(QUESTIONS);level='sl' if num<=720 else 'ahl';ps=[];ms=[]
    for i,(prompt,steps) in enumerate(parts):
        label=chr(97+i);ps.append({'label':label,'prompt':prompt,'marks':len(steps)});ms.append({'part':label,'steps':[{'code':c,'text':t} for c,t in steps]})
    tested=[]
    for label,actual,expected in numerics:
        assert math.isclose(actual,expected,rel_tol=1e-7,abs_tol=1e-10),(num,label,actual,expected)
        tested.append({'quantity':label,'actual':actual,'expected':expected,'status':'passed'})
    assert tested
    q={'id':f'ib-bio-d-{num}','number':num,'subject':'biology','topicId':'continuity-change','collectionId':'biology-continuity-change','syllabusCode':code,'subtopic':TITLES[code],'level':level,'difficulty':'hard','calculator':True,'questionType':'data-based','title':title,'stem':stem+'\n\nAll datasets and schematics in this question are constructed for practice. Give numerical answers with appropriate units and precision.','diagramSvg':figure,'diagramCaption':'Original constructed scientific figure. Schematics show relevant relationships; use the stated measurements for calculations.','parts':ps,'markScheme':ms,'marks':sum(p['marks'] for p in ps),'answerSummary':' '.join(t for _,steps in parts for c,t in steps if c=='A1'),'verification':{'method':'Original author derivation, explicit data checks and biological interpretation; separate independent review before release','notes':reason},'source':{'document':'Independent syllabus-authored practice','question':num},'status':'published'}
    assert 6<=q['marks']<=14,(num,q['marks'])
    QUESTIONS.append(q);RECORDS.append({'id':q['id'],'status':'passed','checks':tested,'biologicalReasoning':reason})

add('D1.1','Two different fractions in a density-label experiment',
 'Bacteria initially contain only heavy-isotope DNA. After transfer to light-isotope medium, all DNA is copied once per generation. The figure shows heavy DNA initially, a single intermediate band after generation 1, and intermediate plus light bands after generation 2. Every original heavy strand remains intact; newly made strands contain only light isotope. Assume equal DNA lengths, no degradation and complete replication.',
 density([('Initial',[(290,'heavy')]),('Generation 1',[(210,'intermediate')]),('Generation 2',[(210,'intermediate'),(130,'light')])]),[
 P('Explain why the generation-1 result rejects the simple conservative model and how generation 2 distinguishes semiconservative from the simple dispersive model.',R('Conservative copying predicts separate unchanged heavy and entirely light molecules after one generation, rather than one intermediate band.'),R('Semiconservative copying retains one old strand in each first-generation molecule; subsequent copying produces both hybrid and entirely light molecules.'),R('Simple dispersive copying predicts mixtures of old/new material within all molecules, with a shifting intermediate band rather than a distinct entirely light band.')),
 P('At generation 3, calculate the fraction of double-stranded molecules that still contain heavy material and the fraction of all DNA strands that are heavy.',M('Starting from one molecule, there are eight double-stranded molecules and sixteen strands after three generations.'),A('Two molecules contain an original heavy strand: 2/8 = 1/4 are hybrid.'),A('Only the two original strands are heavy: 2/16 = 1/8 of strands are heavy.')),
 P('Explain why equal band widths in the schematic do not justify a 1:1 amount ratio at generation 3.',R('The drawing specifies band positions, not calibrated amounts. Semiconservative tracking predicts a 1:3 hybrid:light molecule ratio at generation 3.'))],
 [('hybrid fraction',2/2**3,.25),('heavy strand fraction',2/(2*2**3),.125)],'Shared semiconservative concept; no polymerase directionality required. Separate molecule and strand denominators; conservative/dispersive predictions explicitly compared.')

add('D1.1','A matching DNA profile is evidence with a denominator',
 'An unknown DNA sample U and reference samples A and B are profiled at two markers. All bands are resolved, and both alleles at each marker are represented by the shown pattern; U and A match at both markers, while B differs. In the relevant reference population, the two matching marker-genotype frequencies are 0.080 and 0.050. For this calculation assume independence between markers, a single-source sample and error-free typing.',
 gel([('U',[135,175,245,290]),('A',[135,175,245,290]),('B',[135,190,245,275])],'Two-marker DNA-profile comparison'),[
 P('Compare the references with U and calculate the probability that a randomly selected unrelated individual from the stated population matches both markers.',A('A is consistent with all shown U bands; B is excluded under the stated error-free single-source assumptions.'),M('Multiply the genotype-match frequencies because independence is supplied.'),A('Random-match probability = 0.080 × 0.050 = 0.00400, or 0.400%.')),
 P('Evaluate the statement “there is therefore a 99.6% probability that A is the source”.',R('A random-match probability concerns an unrelated individual’s profile, not the probability of source identity conditional on a match.'),R('The source conclusion also depends on the number of possible sources, prior/contextual evidence and contamination or typing risks.')),
 P('Explain how adding informative independent markers changes evidential strength, and give a reason independence must be checked.',R('Further marker-match frequencies below one reduce the combined random-match probability if genuinely independent.'),R('Linked or population-associated markers may not be independent; multiplying marginal frequencies without checking can overstate the strength of a match.'))],
 [('random match probability',.08*.05,.004),('percent',.08*.05*100,.4)],'Shared DNA-profile interpretation and reliability. No inverse-probability fallacy or individual guilt conclusion; band positions are uncalibrated.')

add('D1.1','PCR amplification and a contaminated control',
 'A PCR begins with four double-stranded target molecules. For cycles 1–10 each molecule produces one additional copy per cycle. In cycles 11–15 the expected fractional increase per cycle is 0.80, so multiply by 1.80 per cycle. Treat this as an expected-value model. A separate gel shows a target-sized band in the sample S, positive control P and no-template control N.',
 gel([('S',[190]),('P',[190]),('N',[190])],'PCR controls with a target-sized band in the no-template lane'),[
 P('Calculate the expected target-molecule count after cycle 15 and its fraction of the perfect-doubling prediction.',M('After cycle 10 there are 4 × 2¹⁰ = 4096 molecules.'),A('After cycle 15 the expected count is 4096 × 1.80⁵ ≈ 7.74 × 10⁴ molecules.'),A('Perfect doubling gives 4 × 2¹⁵ = 131072; expected yield is (1.80/2)⁵ = 59.0% of this.')),
 P('Explain why the sample band cannot yet be accepted as reliable evidence that the original sample contained the target.',R('The no-template control should not amplify target DNA; its band indicates contamination or another source of false amplification.'),R('A positive sample band can then arise from the same problem. Repeat with clean reagents and contamination controls before accepting the result.')),
 P('Relate the roles of heat, primers and Taq polymerase to amplification.',R('Heating separates the DNA strands; cooling allows primers to pair with target regions.'),R('Taq extends from paired primers and tolerates repeated high-temperature strand-separation cycles; primers help define which region is amplified.'))],
 [('cycle15 expected',4096*1.8**5,77396.70528),('fraction of ideal',(1.8/2)**5,.59049)],'Shared PCR includes primers and Taq, but no AHL primase/leading-lagging demands. Expected count is not misrepresented as an exact integer observation.')

b=box(70,75,640,72,'Reference mRNA segment: AUG | GAA | UUU | UGA')+box(70,175,300,80,'Variant X\nAUG | GAG | UUU | UGA')+box(410,175,300,80,'Variant Y\nAUG | GAA | UUA | UGA')+txt(390,325,'Supplied code: AUG Met; GAA/GAG Glu; UUU Phe; UUA Leu; UGA stop.',15)
add('D1.2','A substitution can preserve sequence or change a side chain',
 'The reference mRNA segment and two single-base variants are shown. Use the supplied code: AUG = methionine, GAA/GAG = glutamate, UUU = phenylalanine, UUA = leucine and UGA = stop. Read the displayed mRNA left to right. No regulatory or splicing effects are included in this model.',svg(b,'Codon comparison using a supplied translation key'),[
 P('Deduce the amino-acid sequence represented by each segment and state why the stop codon is not an additional amino acid.',A('Reference: Met–Glu–Phe; X: Met–Glu–Phe; Y: Met–Glu–Leu.'),R('A stop codon signals termination and does not encode an amino acid.')),
 P('Explain how X illustrates degeneracy and why this does not establish that every substitution is harmless.',R('Two different codons, GAA and GAG, encode the same amino acid in the supplied code, so X preserves the primary sequence.'),R('Other substitutions can change an amino acid or create/remove a stop; Y changes phenylalanine to leucine. Phenotypic effects depend on the affected protein region.')),
 P('The three-amino-acid product is treated as a complete short peptide in this model. State how many peptide bonds form and explain the distinction between codon and anticodon.',A('Two peptide bonds connect three amino acids.'),R('A codon is an mRNA triplet; a complementary tRNA anticodon helps match an amino acid to a sense codon. A stop is not decoded by an amino-acid-carrying tRNA.'))],
 [('peptide bonds',3-1,2),('sense codons',4-1,3)],'SL elongation/code interpretation, not AHL directionality or ribosome-site requirements. Degeneracy is not generalized to every mutation.')

b=box(285,65,210,55,'Early embryo')+arrow(390,120,180,200)+arrow(390,120,590,200)+box(65,205,235,65,'Lineage A\nbody cells only')+box(455,205,270,65,'Lineage B\nbody cells + gametes')+txt(390,325,'A mutation in B is found in 20% of its mature gametes.',16)
add('D1.3','A mosaic mutation does not have a fixed one-half transmission risk',
 'In a model diploid animal, an early mutation occurs in lineage B, which later contributes to both body tissues and gametes. Lineage A contributes only to body tissues. Testing shows the mutation in 20.0% of mature gametes. Assume fertilizations independently sample those gametes, the other parent lacks the mutation, and offspring viability is unaffected.',svg(b,'Developmental lineages and a measured mutant-gamete fraction'),[
 P('Explain why the mutation can be inherited even if many body cells lack it, and why a mutation restricted to A would have a different consequence.',R('B contributes to the germline, so some gametes can carry the mutation despite mosaic body tissues.'),R('A contributes only to somatic tissues in the model, so a mutation confined to A would not be transmitted through these gametes.')),
 P('Calculate the probability that at least one of four offspring inherits the mutation. Explain why automatically using a 1/2 gamete probability is unjustified.',M('The probability that none inherits it is (1−0.200)⁴.'),A('At least one inherits it with probability 1−0.800⁴ = 0.5904, or 59.04%.'),R('The measured gamete fraction is 20%, rather than the uniform heterozygous germline assumed by a simple 1:1 segregation model.')),
 P('Evaluate the inference that the mutation occurred because the animal needed a new trait.',R('The lineage and transmission data concern where a mutation arose and how it is inherited; they do not show a need-directed origin.'),R('Mutations supply new variation; selection can subsequently alter the frequency of heritable variants.'))],
 [('at least one transmitted',1-.8**4,.5904)],'Shared somatic/germline and mutation randomness. Explicit assumptions support probability; no patient diagnosis or real-family inference.')

