    y=115+i*58;b+=txt(75,y+5,f'Chromatid {i+1}',14,'start')+line(230,y,440,y,BLUE if left=='A' else ORANGE,5)+line(440,y,680,y,BLUE if right=='A' else ORANGE,5)+circle(285,y,6,fill='#fff')
