b+=txt(390,385,'Filled circles: methylated promoter sites; five scored sites in this model.',14)
add('D2.2','A persistent expression change can occur without a sequence change',
 'A cloned cell population initially has four of five scored promoter cytosines methylated and relative mRNA abundance 20. A targeted demethylating treatment leaves one of five methylated and mRNA abundance 80. The promoter base sequence remains unchanged. The altered tag pattern and expression persist through two mitotic passages after treatment removal. A vehicle-treated clone retains the original pattern.',svg(b,'Constructed promoter-tag and expression comparison'),[
 P('Calculate promoter methylation percentages and the mRNA fold change, then explain the relationship to transcriptional control.',A('Methylation changes from 4/5 = 80% to 1/5 = 20%; mRNA increases fourfold.'),R('Promoter cytosine methylation can repress downstream transcription; removing these tags is consistent with increased expression in the tested cells.')),
 P('Explain why the result is an example of an epigenetic change and what the passages add to the evidence.',R('The expression/tag pattern changes without alteration of the DNA base sequence, distinguishing it from a sequence mutation.'),R('Persistence through mitotic passages supports transmission of the expression state to daughter cells beyond the immediate treatment exposure.')),
 P('Evaluate the claims that this proves inheritance through gametes and that histone methylation always has the same transcriptional effect as promoter methylation.',R('Mitotic persistence in this cell culture does not establish transmission through meiosis or offspring; many gametic epigenetic tags are reset.'),R('Histone methylation can activate or repress transcription depending on context; its effect must not be generalized from this promoter-cytosine result.'))],
 [('initial methylation %',4/5*100,80),('final methylation %',1/5*100,20),('mRNA fold',80/20,4)],'D2.2 AHL. Promoter methylation versus context-dependent histone tags; no unsupported details of histone chemistry or proof of transgenerational inheritance.')

b=txt(390,70,'External water potential = −250 kPa',18)
for x,lab,ss,pp in [(145,'A',-600,400),(390,'B',-450,100),(635,'C',-300,0)]:
    b+=circle(x,210,85)+txt(x,165,lab,20)+txt(x,205,f'Ψs = {ss} kPa',16)+txt(x,245,f'Ψp = +{pp} kPa',16)
b+=txt(390,370,'Use Ψw = Ψs + Ψp; compare the totals, not Ψs alone.',16)
add('D2.3','A pressure term can reverse a solute-only prediction',
 'Three plant cells are in contact with an external solution of water potential −250 kPa. Cell A has Ψs = −600 and Ψp = +400 kPa; B has −450 and +100; C has −300 and 0. Use Ψw = Ψs + Ψp. All values use the same reference and temperature. For a short model adjustment of B only, assume its solute component remains fixed while pressure changes.',svg(b,'Constructed cell water-potential components'),[
 P('Calculate each cell’s total water potential and predict initial net water movement relative to the external solution.',A('A: −200 kPa; B: −350 kPa; C: −300 kPa.'),R('Water moves from higher to lower water potential: initially out of A, into B and into C.')),
 P('For the stated short adjustment of B, calculate the pressure potential at equilibrium with the external solution.',M('Set −250 = −450 + Ψp while retaining the stipulated fixed solute component.'),A('Ψp = +200 kPa.')),
 P('Explain why A disproves a prediction based only on comparing solute concentration and state a limitation of treating B’s solute component as fixed.',R('A’s positive pressure raises its total above the external value despite its more negative solute potential, so initial water movement is outward.'),R('Real water entry changes cell volume and can dilute solutes; Ψs need not remain constant during a large adjustment. The computed pressure applies to the stated limited model.'))],
 [('A total',-600+400,-200),('B total',-450+100,-350),('C total',-300+0,-300),('B final pressure',-250-(-450),200)],'AHL water-potential components and pressure; explicit approximation boundary avoids treating real dilution as unchanged solute concentration.')

b=box(75,95,245,230,'')+f'<rect x="77" y="97" width="241" height="226" rx="3" fill="#e7f0f8" stroke="{BLUE}" stroke-width="2"/>'+txt(195,70,'Fresh cell',18)+txt(195,365,'Ψs = −600 kPa; Ψp = +400',14)
b+=box(460,95,245,230,'')+f'<rect x="466" y="101" width="233" height="218" rx="16" fill="#e7f0f8" stroke="{BLUE}" stroke-width="2"/>'+txt(580,70,'Incipient plasmolysis',18)+txt(580,365,'External Ψw = −750 kPa',14)
add('D2.3','At incipient plasmolysis the pressure component is zero',
 'A fresh plant cell has Ψs = −600 kPa and Ψp = +400 kPa. After equilibration in an external solution of Ψw = −750 kPa, it is just at incipient plasmolysis, where turgor pressure is zero. For a supplied ideal fixed-temperature model, solute amount is conserved and Ψs is inversely proportional to protoplast volume. The cell sketches are schematic and do not encode a volume scale.',svg(b,'Cell wall and protoplast states; black outline is wall, blue is membrane'),[
 P('Calculate the initial total water potential and the final solute potential at the stated plasmolysis point.',A('Initially Ψw = −600 + 400 = −200 kPa.'),A('At equilibrium Ψw = −750 kPa and Ψp = 0, so final Ψs = −750 kPa.')),
 P('Use the supplied inverse-volume model to calculate final protoplast volume as a fraction of its initial value and the percentage decrease.',M('With conserved solute amount at fixed temperature, Ψs,initial × Vinitial = Ψs,final × Vfinal.'),A('Vfinal/Vinitial = (−600)/(−750) = 0.800; volume decreases by 20.0%.')),
 P('Explain the initial movement and evaluate assigning pressure potential −750 kPa to the plasmolyzed cell.',R('The initial cell total −200 kPa exceeds external −750 kPa, so water initially leaves; solutes become more concentrated as protoplast volume falls.'),R('At the stipulated incipient plasmolysis point the pressure term is zero, not the negative external total; assigning −750 to Ψp confuses separate components.'))],
 [('initial total',-600+400,-200),('final volume fraction',600/750,.8),('volume decrease %',(1-600/750)*100,20)],'AHL pressure/solute components with explicitly supplied inverse-volume rule. Schematic dimensions are not measured and are not used as a volume scale.')

b=box(60,65,255,60,'Primary spermatocyte\nafter DNA replication')+box(465,65,255,60,'Primary oocyte\nafter DNA replication')
for x in [95,160,225,290]:b+=circle(x,270,25)
b+=circle(525,265,45)
for x,y in [(620,240),(670,270),(620,310)]:b+=circle(x,y,14)
b+=arrow(185,140,185,215)+arrow(590,140,590,200)+txt(190,350,'Four similar-sized products',15)+txt(590,350,'One large + three small products',15)
add('D3.1','Equal chromosome reduction can accompany unequal cytoplasmic allocation',
 'Ten primary spermatocytes and ten primary oocytes each complete the modeled meiotic sequence. For counting only, assume each primary oocyte ultimately yields one functional ovum and three recovered polar-body products; each primary spermatocyte yields four functional sperm. All start after replication at DNA content 4C, and each final haploid product contains 1C. The diagram represents relative cytoplasmic allocation, not a calibrated volume.',svg(b,'Constructed gametogenesis outcomes with unequal oocyte cytokinesis'),[
 P('Calculate functional gamete counts from the two groups and total DNA content in all recovered meiotic products from either group.',A('The spermatocytes produce 40 functional sperm; the oocytes produce 10 functional ova and 30 polar-body products.'),A('Each group yields 40 haploid products × 1C = 40C total DNA, matching ten starting 4C cells under the stated complete-recovery model.')),
 P('Explain how the oocyte can preserve resources while still reducing chromosome number correctly.',R('Unequal cytokinesis concentrates most cytoplasm and organelles in one functional ovum while chromosomes segregate into haploid products.'),R('Chromosome-set reduction depends on nuclear segregation, not equal allocation of cytoplasmic volume to all products.')),
 P('A sample has normal sperm numbers but greatly reduced fertilization after blocking an acrosomal enzyme. Explain why the gamete count alone does not predict fertilization success.',R('The acrosomal reaction contributes to penetration of egg-associated layers; blocking it can prevent successful entry despite normal sperm production.'),R('Gamete quality and functional steps such as motility, recognition and penetration must also be considered; a cell count is not a direct count of successful fertilizations.'))],
 [('functional sperm',10*4,40),('functional ova',10*1,10),('all products DNA C',10*4*1,40)],'AHL gametogenesis/unequal division and acrosome function. Counting assumptions explicitly specify polar-body completion; no fixed early embryo stages beyond course scope.')

add('D3.1','Sperm entry and normal ploidy need different denominators',
 'In a constructed gamete study, control oocytes show at least one sperm entry in 80% of oocytes; 5% of those entered oocytes are polyspermic. With an acrosome inhibitor, entry is 10% and polyspermy among entered oocytes 4%. With a cortical-reaction inhibitor, entry is 78% and polyspermy among entered oocytes 45%. Assume a single-sperm entry would otherwise produce the normal diploid zygote and ignore later viability.',bars(['Control','Acrosome inhibitor','Cortical inhibitor'],[80,10,78],'Oocytes with ≥1 sperm entry / %','Constructed entry probabilities; polyspermy fractions are separately stated'),[
 P('Calculate the expected percentage of original oocytes forming normal single-sperm zygotes in control and cortical-inhibitor groups.',M('Multiply entry probability by the fraction of entered oocytes with only one sperm.'),A('Control = 0.80 × 0.95 = 0.760, or 76.0% of original oocytes.'),A('Cortical-inhibitor group = 0.78 × 0.55 = 0.429, or 42.9%.')),
 P('Explain how the differing inhibitor effects distinguish acrosomal from cortical functions.',R('The acrosomal reaction helps sperm penetrate egg-associated layers; its inhibition strongly reduces entry.'),R('The cortical reaction helps prevent additional sperm entry after the first; inhibiting it can leave initial entry high while greatly increasing polyspermy.')),
 P('Evaluate the claim that the cortical-inhibitor treatment has almost no effect because 78% is close to 80%.',R('That compares entry alone and ignores the conditional polyspermy proportion; the normal single-sperm outcome is substantially reduced.'),R('Multiple sperm can introduce extra chromosome sets, so entry is not equivalent to normal fertilization and ploidy.'))],
 [('normal control %',.8*.95*100,76),('normal cortical inhibitor %',.78*.55*100,42.9)],'AHL cortical/acrosomal reactions. Every probability has an explicit original-oocyte or entered-oocyte denominator; later development not silently assumed.')

b=box(55,85,220,245,'Maternal blood\nO₂: 80 units\nCO₂: 40 units',fill='#fff4ee')+box(505,85,220,245,'Fetal blood\nO₂: 30 units\nCO₂: 50 units',fill='#eef3f8')
b+=line(335,80,335,335,ORANGE,3)+line(445,80,445,335,BLUE,3)+txt(390,365,'Exchange barrier and villous surface; blood circuits remain separate.',14)
b+=arrow(290,160,490,160,'O₂')+arrow(490,245,290,245,'CO₂')
add('D3.1','Placental exchange does not require the blood circuits to mix',
 'A constructed placental-exchange model has maternal and fetal blood separated by a thin villous barrier. Oxygen partial pressures are 80 and 30 relative pressure units in maternal/fetal blood; carbon dioxide partial pressures are 40 and 50. For a supplied diffusion model, flux is proportional to surface area × partial-pressure difference / barrier thickness. A structural change doubles area and halves thickness; the pressure differences are initially unchanged.',svg(b,'Separate maternal and fetal exchange compartments'),[
 P('Predict initial net movement of oxygen and carbon dioxide and relate the answer to partial-pressure gradients.',A('Oxygen moves from maternal to fetal blood; carbon dioxide moves from fetal to maternal blood.'),R('Each gas initially diffuses from its higher to lower partial pressure across the exchange barrier.')),
 P('Calculate the predicted flux multiplier after the stated structural change and explain why this does not mean real flux can increase indefinitely.',M('The area factor is 2 and inverse-thickness factor is 1/0.5.'),A('Predicted flux increases fourfold while the stated gradients remain unchanged.'),R('Real blood supply, gas delivery and changing gradients can become limiting; the proportional model isolates only the stated structural factors.')),
 P('Explain why fetal and maternal red blood cells need not cross the barrier for gas exchange, and identify which fetal umbilical vessel carries blood returning from the placenta toward the fetus.',R('Gas molecules cross the barrier while the blood circuits remain distinct; wholesale blood-cell mixing is not required.'),A('The umbilical vein carries blood from the placenta toward the fetus, relatively oxygenated compared with the umbilical arteries going to the placenta.'))],
 [('oxygen pressure gradient',80-30,50),('CO2 pressure gradient',50-40,10),('flux multiplier',2/.5,4)],'AHL placental exchange limited to villous area/barrier principles. Pressure is not mislabeled concentration; umbilical vein/artery directions are correct.')

add('D3.2','A dihybrid fit is compatible with a model, not proof of it',
 'A cross AaBb × AaBb involves two unlinked autosomal genes with complete dominance and no viability differences. Observed phenotype counts for A_B_, A_bb, aaB_ and aabb are 180, 65, 55 and 20, total 320. Use χ² = Σ(O−E)²/E and, for this four-category comparison with no parameters fitted, three degrees of freedom. The supplied 5% critical value is 7.815.',bars(['A_B_','A_bb','aaB_','aabb'],[180,65,55,20],'Offspring counted','Constructed unlinked-dihybrid phenotype results'),[
 P('Derive the expected phenotype ratio and expected counts from independent assortment.',R('Each parent produces AB, Ab, aB and ab gametes with probability 1/4; independent segregation and complete dominance give 9:3:3:1.'),A('Expected counts are 180, 60, 60 and 20.')),
 P('Calculate χ² and interpret it using the supplied critical value.',M('Only the middle two categories contribute: (65−60)²/60 + (55−60)²/60.'),A('χ² = 0.833 (approximately), less than 7.815.'),R('Do not reject the stated 9:3:3:1 model at the supplied 5% level; sampling variation can account for this discrepancy.')),
 P('Explain why the result does not prove that the loci are unlinked or that no experimental error occurred.',R('Failure to reject is compatibility with the tested assumptions and sample size, rather than proof that all alternative mechanisms are impossible.'),R('Viability differences, scoring errors or other genetic models require additional evidence; a goodness-of-fit result alone cannot rule them out.'))],
 [('sample total',180+65+55+20,320),('expected A_bb',320*3/16,60),('chi squared',25/60+25/60,.8333333333)],'AHL two unlinked autosomal genes and supplied chi-square reference. Correct degrees of freedom and fail-to-reject interpretation, with explicit phenotype notation.')

b=txt(390,75,'Heterozygous parent: linked allele arrangements on homologues',17)+line(130,145,650,145,BLUE,5)+line(130,225,650,225,ORANGE,5)+txt(250,135,'A',22)+txt(540,135,'B',22)+txt(250,215,'a',22)+txt(540,215,'b',22)+txt(390,310,'Testcross partner: ab / ab',18)+txt(390,365,'Offspring: AB 410; ab 390; Ab 110; aB 90',17)
add('D3.2','A recombination fraction is not automatically a fraction of meioses',
 'A heterozygous parent has linked alleles AB/ab as shown and is testcrossed to ab/ab. Offspring reflect gametes AB 410, ab 390, Ab 110 and aB 90. Assume equal viability and reliable scoring. For the final model only, suppose every relevant meiosis has either no crossover or exactly one crossover between the loci, and one crossover makes two of four chromatids recombinant.',svg(b,'Linked homologues and a constructed testcross'),[
 P('Identify parental and recombinant classes and calculate the recombination fraction.',A('AB and ab are parental classes; Ab and aB are recombinant.'),M('Use both recombinant classes divided by all offspring.'),A('Recombination fraction = (110+90)/1000 = 0.200, or 20.0%.')),
 P('Under the supplied single-crossover model, calculate the fraction of meioses that had a crossover in the interval.',R('A crossover meiosis contributes recombinant chromatids in only half its products.'),A('If half the products of fraction f of meioses are recombinant, 0.5f = 0.20 and f = 0.40, or 40.0%.')),
 P('Explain one reason the conversion from 20% to 40% would not be justified without the extra assumptions.',R('Multiple crossovers can restore parental marker combinations, and chromatid sampling/viability can also affect observed offspring classes.'),R('Thus a recombinant-offspring fraction does not universally measure the same fraction of meiotic events; the relationship depends on the specified crossover model.'))],
 [('total offspring',410+390+110+90,1000),('recombination',200/1000,.2),('single-crossover meiosis fraction',.2/.5,.4)],'AHL linked alleles drawn on homologous chromosome lines. The nonstandard meiosis-fraction inference is fully defined by a supplied two-of-four rule; no memorized mapping unit required.')

add('D3.2','Post-fertilization selection can mimic a linkage pattern',
 'An AaBb × aabb testcross is scored at two stages. Among hatchlings the four genotype classes AB/ab, ab/ab, Ab/ab and aB/ab each contain 100 individuals. In the same tracked cohort, adults number 90, 90, 10 and 10 respectively. Use a 1:1:1:1 goodness-of-fit model, χ² = Σ(O−E)²/E, three degrees of freedom, and supplied 5% critical value 7.815.',bars(['AB/ab','ab/ab','Ab/ab','aB/ab'],[90,90,10,10],'Adults surviving from 100 hatchlings per class','Constructed stage-specific survival in a testcross cohort'),[
 P('Calculate expected adult counts under equal survival and the adult χ² value.',M('There are 200 adults, so equal survival predicts 50 in each class.'),A('χ² = 4 × 40²/50 = 128.'),R('This exceeds 7.815, so reject equal adult-class proportions at the stated level under the model.')),
 P('Explain why using only the adult recombinant-looking classes to infer a 10% gametic recombination fraction would be misleading.',A('The adult minority classes total 20/200 = 10%, but the corresponding hatchling classes were 200/400 = 50%.'),R('Strong genotype-dependent survival changed proportions after fertilization; adult proportions do not directly represent gamete production in this cohort.')),
 P('State what evidence favors a viability explanation over linkage alone and one additional control that would strengthen that conclusion.',R('All four classes were equally frequent at hatching before their sharply unequal survival, whereas a gamete-production bias should already affect early class frequencies.'),R('Check genotype scoring and track replicate families under randomized conditions to test whether the survival difference is reproducible rather than a batch or identification effect.'))],
 [('adult total',90+90+10+10,200),('adult chi squared',4*40**2/50,128),('adult minority fraction',20/200,.1),('initial minority fraction',200/400,.5)],'AHL dihybrid/testcross inference and chi-square. Same tracked cohort has no impossible gains in counts. Viability confounding distinguished from meiotic linkage.')

b=box(65,105,210,75,'Blood plasma\nMarker: 0.020 mg mL⁻¹')+arrow(275,142,340,142,'Filter')+box(345,105,190,75,'Filtrate')+arrow(440,180,440,250)+box(330,255,390,85,'Urine: 1.00 mL min⁻¹\nMarker: 2.40 mg mL⁻¹')+txt(390,385,'Marker is freely filtered and neither reabsorbed nor secreted.',15)
add('D3.3','Renal amounts require both concentration and flow',
 'An inert marker is freely filtered by a model kidney and is neither reabsorbed nor secreted. Plasma marker concentration is 0.020 mg mL⁻¹, urine concentration 2.40 mg mL⁻¹ and urine flow 1.00 mL min⁻¹. Use filtered marker amount per minute = excreted marker amount per minute. Plasma urea is 5.00 mmol dm⁻³ and urine urea 300 mmol dm⁻³. For urea only, assume no secretion or production in the nephron.',svg(b,'Constructed kidney marker-flow model'),[
 P('Calculate glomerular filtration rate from the marker data, including units.',M('Excreted marker = 2.40 mg mL⁻¹ × 1.00 mL min⁻¹ = 2.40 mg min⁻¹.'),A('Filtration rate = 2.40 mg min⁻¹ / 0.020 mg mL⁻¹ = 120 mL min⁻¹ = 0.120 dm³ min⁻¹.')),
 P('Calculate filtered and excreted urea per minute, then its net reabsorbed fraction under the stated assumptions.',M('Filtered urea = 5.00 × 0.120 = 0.600 mmol min⁻¹; excreted = 300 × 0.00100 = 0.300 mmol min⁻¹.'),A('Net reabsorbed urea = 0.300 mmol min⁻¹, or 50.0% of the filtered amount.')),
 P('Explain why a urine urea concentration much greater than plasma does not by itself prove secretion of urea into the nephron.',R('Reabsorption of water can concentrate the urea remaining in the tubule even while some urea is reabsorbed.'),R('Amount flux, not concentration alone, determines the balance; the urine flow is far below the filtration flow in this model.'))],
 [('GFR mL/min',2.40*1/.020,120),('filtered urea mmol/min',5*.120,.6),('excreted urea mmol/min',300*.001,.3),('urea fraction reabsorbed',(.6-.3)/.6,.5)],'AHL kidney filtration/reabsorption with an explicitly supplied marker balance. Rates and unit conversions avoid the concentration-versus-amount fallacy; no clinical diagnostic interpretation.')

add('D3.3','ADH changes water permeability rather than pumping water',
 'A constructed collecting-duct model has urine flow 1.00 mL min⁻¹ and osmolar concentration 1600 milliosmoles dm⁻³ with high ADH, compared with 8.00 mL min⁻¹ and 200 milliosmoles dm⁻³ with low ADH. Treat osmolar concentration as dissolved-particle amount per volume for this calculation. A second manipulation prevents normal sodium transport by the ascending limb and reduces the medullary gradient despite high ADH.',bars(['High ADH','Low ADH'],[1,8],'Urine flow / mL min⁻¹','Constructed ADH response at fixed particle-excretion load'),[
 P('Calculate urine volume and dissolved-particle amount excreted in 30 minutes in each ADH condition.',A('Volumes are 30.0 mL = 0.0300 dm³ with high ADH and 240 mL = 0.240 dm³ with low ADH.'),M('Multiply each volume by its osmolar concentration in matching volume units.'),A('Both excrete 48.0 milliosmoles: 0.0300 × 1600 and 0.240 × 200.')),
 P('Explain how ADH can change volume/concentration without changing this particle-excretion load.',R('ADH increases aquaporin-mediated collecting-duct water permeability, allowing more water reabsorption along the medullary osmotic gradient.'),R('Water is moving by osmosis rather than being actively pumped by ADH; less remaining water concentrates the excreted particles.')),
 P('Explain why high ADH alone does not restore the original urine concentration when the medullary gradient is reduced.',R('Increased permeability requires an appropriate water-potential gradient to drive reabsorption.'),R('Ascending-limb sodium transport contributes to that medullary gradient; weakening it can reduce water removal even when collecting ducts contain aquaporins.'))],
 [('high ADH 30min volume dm3',1*30/1000,.03),('low ADH particles',8*30/1000*200,48),('high ADH particles',1*30/1000*1600,48)],'AHL ADH/aquaporins and the restricted ascending-limb/medullary-gradient account. Particle concentration defined; no claim water is actively transported.')

q_after=(336+2*18)/(2*(490+336+18))
add('D4.1','Selection survivors need not already be in Hardy–Weinberg proportions',
 'An initial model population contains AA 490, Aa 420 and aa 90 individuals. Viability to breeding is 1.00, 0.80 and 0.20 respectively; ignore other fitness differences and migration. All surviving breeders then mate randomly in a very large population, with ordinary segregation and no new mutation. Use p+q=1 and p²:2pq:q² for the next zygote generation under those assumptions.',bars(['AA before','Aa before','aa before','AA survivors','Aa survivors','aa survivors'],[490,420,90,490,336,18],'Individuals / expected survivors','Constructed genotype-dependent viability selection'),[
 P('Calculate initial allele frequency q and show whether the initial genotype counts fit Hardy–Weinberg proportions.',M('q = (420 + 2×90)/(2×1000).'),A('q = 0.300 and p = 0.700; expected genotype fractions are 0.49, 0.42 and 0.09, matching the initial counts.')),
 P('Calculate surviving genotype counts and the new a-allele frequency among breeders.',A('Survivors: AA 490, Aa 336, aa 18; total 844.'),M('Count a copies in survivors and divide by twice all surviving individuals.'),A('q = (336+36)/1688 = 0.2204 approximately.')),
 P('Predict the aa fraction among the next zygotes and explain why 18/844 is not the Hardy–Weinberg prediction for them.',A('Next-generation aa fraction = q² ≈ 0.04857, or 4.86%.'),R('18/844 is the observed selected-adult genotype fraction; viability selection has altered genotype proportions. Random mating uses the breeders’ allele frequencies to form the next zygote proportions.'))],
 [('initial q',(420+2*90)/2000,.3),('survivors',490+420*.8+90*.2,844),('survivor q',q_after,372/1688),('next aa',q_after*q_after,(372/1688)**2)],'AHL allele counting/Hardy–Weinberg and viability selection. Selected adult genotype fractions are not automatically equilibrium zygote proportions.')

xs=list(range(1,10))
add('D4.1','Similar population means can hide different selection patterns',
 'Three constructed environments have the illustrated survival probabilities across a heritable quantitative trait. S1 favors intermediate values; S2 increases survival toward larger values; S3 favors both extremes over intermediate values. At trait values 2 and 5, S1 survival probabilities are 0.640 and 1.00. Assume equal reproduction among survivors when comparing this component of fitness.',chart([('S1',[(x,1-((x-5)/5)**2) for x in xs]),('S2',[(x,x/10) for x in xs]),('S3',[(x,.2+((x-5)/5)**2) for x in xs])],'Heritable trait / arbitrary units','Survival probability','Constructed survival functions in three environments',xrange=(1,9),yrange=(0,1.1)),[
 P('Identify the selection pattern in each environment and compare the predicted effect on trait variation.',A('S1 is stabilizing, S2 directional toward larger trait values, and S3 disruptive.'),R('S1 tends to reduce extreme values; S2 shifts favored values toward one side; S3 favors both tails and can maintain/increase separation of trait classes.')),
 P('Calculate the relative survival advantage of trait 5 over trait 2 under S1, expressed as a percentage increase relative to trait 2.',M('Compare the difference with the trait-2 baseline: (1.00−0.640)/0.640.'),A('Relative increase = 56.25%; this differs from the 36-percentage-point probability difference.')),
 P('Evaluate the claims that an unchanged mean proves no selection occurred and that disruptive selection proves new species have formed.',R('Opposite changes in extremes or reduced variation can leave a similar mean, so the distribution and fitness pattern matter.'),R('Disruptive survival differences alone do not demonstrate reproductive isolation or separate species; mating patterns and divergence evidence are needed.'))],
 [('relative survival increase %',(1-.64)/.64*100,56.25),('probability point difference',(1-.64)*100,36)],'AHL directional/stabilizing/disruptive selection with explicit heritability assumption. Mean, spread and speciation claims are carefully separated.')

add('D4.1','A breeding response is not a percentage of height caused by genes',
 'A constructed plant-breeding study begins with mean height 20.0 cm. Breeders deliberately select parents averaging 30.0 cm. Their offspring, grown in a common environment, average 22.0 cm, while offspring of randomly selected control parents average 20.0 cm. Separately, extra nutrient supply makes clones average 30.0 cm, but their untreated descendants average 20.0 cm. For one descriptive ratio, divide the offspring response above control by the selected-parent difference above the initial mean.',bars(['Initial population','Selected parents','Selected offspring','Control offspring'],[20,30,22,20],'Mean height / cm','Constructed artificial-selection and common-environment results'),[
 P('Calculate the descriptive response ratio using the supplied definition.',M('Offspring response = 22−20 = 2 cm; selected-parent difference = 30−20 = 10 cm.'),A('Response ratio = 2/10 = 0.200.')),
 P('Explain why the selected-offspring comparison supports an inherited response more strongly than the nutrient-treated clone comparison.',R('Selected-parent descendants remain taller than control descendants in a common environment, consistent with inherited differences associated with deliberate breeding.'),R('Nutrient-treated clones change height, but their untreated descendants return to control height; that pattern is consistent with a direct environmental response rather than the demonstrated inherited response.')),
 P('Evaluate the claim that the 0.200 ratio means exactly 20% of every plant’s height is genetic. Distinguish deliberate breeding from incidental antibiotic selection.',R('This is a response-to-selection ratio for a specified population/environment; it does not divide an individual’s height into genetic and environmental centimeter portions or identify one causal gene.'),R('Breeders intentionally choose reproducing plants, an artificial-selection process. Unintended antibiotic resistance reflects natural selection under a human-created pressure, rather than intentional choice of resistant organisms for breeding.'))],
 [('descriptive response ratio',(22-20)/(30-20),.2)],'AHL detailed artificial selection. The supplied ratio is interpreted descriptively, not generalized as a gene-caused percentage of individual phenotype; common-environment limitations remain.')

add('D4.2','A chronosequence is a hypothesis about time built from space',
 'Four substrate-age classes in a constructed primary-succession study are 0, 20, 60 and 120 years. Mean plant biomass indices are 0, 4, 18 and 35; mean soil-nitrogen indices are 0.2, 1.0, 3.0 and 5.0. Different sites represent the ages, with four independent sites in each class. The sites have broadly comparable climate but may differ in initial rock chemistry and dispersal access.',chart([('biomass index',[(0,0),(20,4),(60,18),(120,35)])],'Estimated substrate age / years','Plant biomass / relative index','Constructed primary-succession chronosequence'),[
 P('Explain two mechanisms by which early colonists can facilitate later plant establishment.',R('Colonists can contribute organic matter and promote soil development, improving water retention and rooting conditions.'),R('Changes to nutrient availability and local microclimate can make the initially bare substrate suitable for additional species.')),
 P('Calculate the biomass increase from age 20 to 120 as a percentage of age-20 biomass and compare it with the nitrogen-index change over that interval.',A('Biomass increase = (35−4)/4 × 100 = 775%.'),A('Nitrogen index increases from 1.0 to 5.0, a 400% increase; different relative changes do not establish a fixed causal proportionality.')),
 P('Evaluate the claim that every age-20 site will necessarily have index 35 after exactly 100 further years.',R('A space-for-time comparison assumes sites are otherwise comparable; initial substrate, dispersal and disturbance differences can change trajectories.'),R('The means are not a time-resolved fate for every individual site, and succession can be arrested, disturbed or follow alternative pathways.'))],
 [('biomass increase %',(35-4)/4*100,775),('nitrogen increase %',(5-1)/1*100,400)],'AHL primary succession and chronosequence limitations. Nitrogen values are supplied but not put on a misleading common numeric axis with biomass.')

add('D4.2','Removing a disturbance can release arrested succession',
 'In a constructed restoration experiment, six independent landscape blocks each contain randomly assigned plots in a two-factor design. After ten years, mean shrub cover is 20% with grazing/no seed addition, 25% with grazing/seed addition, 60% with grazing exclusion/no seeds and 70% with exclusion/seed addition. Initial cover is comparable at about 15%. No inferential statistical test is supplied.',bars(['Grazed, no seeds','Grazed + seeds','Excluded, no seeds','Excluded + seeds'],[20,25,60,70],'Shrub cover / %','Constructed blocked restoration experiment'),[
 P('Calculate the grazing-exclusion effect within each seed treatment and the seed-addition effect within each grazing treatment.',A('Exclusion raises cover by 40 percentage points without seeds and by 45 with seeds.'),A('Seed addition raises cover by 5 points under grazing and by 10 under exclusion.')),
 P('Explain how the results can support arrested succession rather than an abiotic inability of the site to support shrubs.',R('Shrubs establish much more extensively when grazing is excluded, even without added seeds, so continued disturbance can hold back later vegetation stages.'),R('Existing-site conditions allow shrub establishment under the exclusion treatment; grazing can therefore maintain an earlier community rather than the site being intrinsically incapable of change.')),
 P('Evaluate the strength and limit of the causal interpretation.',R('Random assignment within independent blocks and a seed factor help isolate effects from initial location differences and seed limitation.'),R('Means alone do not establish statistical significance or a universal endpoint; assess block variation, replicate consistency and longer-term outcomes before extending the claim.'))],
 [('exclusion effect without seeds',60-20,40),('exclusion effect with seeds',70-25,45),('seed effect excluded',70-60,10)],'AHL arrested succession and human disturbance. Percentage-point changes distinguished from percent increases; blocks are independent units, not all seedlings.')

stages=[['E','E','M','M','L','L'],['M','L','L','E','E','M'],['L','M','E','L','M','E']]
b=''
for row,(time,states) in enumerate(zip([0,10,20],stages)):
    y=115+row*95;b+=txt(65,y+5,f'Year {time}',15)
    for i,state in enumerate(states):b+=box(135+i*100,y-28,75,55,state,{'E':'#eef3f8','M':'#e6efdf','L':'#ffead8'}[state])
b+=''.join(txt(172.5+i*100,65,f'Patch {i+1}',14) for i in range(6))+txt(390,395,'E = early; M = middle; L = late community stage',15)
add('D4.2','A stable regional mosaic can contain changing patches',
 'Six equally sized habitat patches are surveyed at years 0, 10 and 20. The figure records early (E), middle (M) and late (L) community stages. All three stages remain represented in two patches at each survey, but individual patches change. Local disturbance and vegetation feedbacks allow stages to recur rather than following one irreversible region-wide sequence.',svg(b,'Constructed repeated surveys of a cyclical-succession mosaic'),[
 P('Calculate the late-stage fraction at each survey and determine whether the same patches remain late throughout.',A('Each survey has 2/6 = 1/3, or about 33.3%, late-stage area.'),A('No patch remains L at all three surveys; unchanged regional proportion does not mean unchanged patch identity.')),
 P('Explain how this illustrates stability at one spatial scale and succession at another.',R('The region maintains a similar distribution of stages while local patch communities change over time.'),R('Cyclical or recurrent succession can maintain a shifting mosaic; stability need not mean no biological change or one permanent climax everywhere.')),
 P('Identify a limitation of the ten-year sampling interval and a measurement that would improve interpretation.',R('Unobserved changes between surveys could include additional transitions or different transition sequences; three snapshots do not reconstruct every pathway.'),R('Use more frequent permanent-patch surveys with disturbance, species and environmental records to test proposed cycles rather than inferring them only from stage labels.'))],
 [('late fraction',2/6,1/3),('late patches at all times',sum(all(stages[t][i]=='L' for t in range(3)) for i in range(6)),0)],'AHL cyclical succession. Equal patch areas specified for converting counts to regional area; regional stability does not imply static local communities.')

add('D4.3','Small shifts in hatching need not track a large shift in prey',
 'A constructed great-tit/caterpillar model compares a cool and a warm spring. Caterpillar peak biomass occurs on year-days 140 and 125 respectively; chick hatching occurs on days 135 and 132. Peak chick food demand occurs seven days after hatching. In this model, caterpillar timing responds strongly to spring temperature, whereas bird breeding timing responds partly to photoperiod. These illustrative values are not a reported field dataset.',bars(['Cool prey peak','Cool food demand','Warm prey peak','Warm food demand'],[140,142,125,139],'Day of year','Constructed timing of prey supply and chick demand'),[
 P('Calculate absolute mismatch between peak prey and peak chick demand in each spring and the increase in mismatch.',A('Cool: demand day 142 and prey day 140, mismatch 2 days. Warm: demand day 139 and prey day 125, mismatch 14 days.'),A('Mismatch increases by 12 days even though hatching itself advances by 3 days.')),
 P('Explain why the different environmental cues can produce this result and predict one possible effect on chick performance.',R('Temperature-driven prey development can advance more than bird breeding if the latter remains constrained by photoperiod or other cues.'),R('Peak chick demand can then occur after prey biomass declines, potentially reducing food delivery, growth or survival.')),
 P('Evaluate the claims that an earlier breeding date proves evolutionary adaptation and that warming always improves synchrony.',R('A timing shift can be plastic or demographic; heritable change across generations requires inheritance/selection evidence, not just different dates.'),R('The calculated example shows reduced synchrony despite earlier hatching; the relative responses of interacting species matter rather than a shared direction of change alone.'))],
 [('cool mismatch',abs((135+7)-140),2),('warm mismatch',abs((132+7)-125),14),('mismatch increase',14-2,12)],'AHL phenological mismatch and supplied cue model, matching a current-course example without attributing invented measurements to a real study.')

add('D4.3','A fractional generation cannot be rounded into another complete life cycle',
 'For a supplied spruce-bark-beetle development model, accumulated degree-days are (mean temperature−10 °C) × season days when temperature exceeds 10 °C. Each complete generation requires 300 degree-days, with no carryover into the next year. Compare seasons: X = 120 days at 15.0 °C; Y = 120 days at 16.5 °C; Z = 150 days at 18.0 °C. For a separate unconstrained population illustration, each completed generation multiplies numbers by three.',bars(['X','Y','Z'],[600,780,1200],'Accumulated degree-days / °C days','Constructed insect-development model'),[
 P('Calculate degree-days and complete generations in each season.',A('X: 600 degree-days, two complete generations; Y: 780, two complete generations plus partial development; Z: 1200, four complete generations.'),R('780/300 = 2.6 does not represent three completed generations under the stated threshold and no-carryover model.')),
 P('Use the separate multiplication model to compare population factors after the complete generations in X and Z.',M('Use 3² for X and 3⁴ for Z, applying only complete generations.'),A('Population factors are 9 and 81; Z’s factor is nine times X’s.')),
 P('Explain two limitations of using these calculations as a precise prediction of a real outbreak.',R('Real temperatures fluctuate and developmental thresholds, mortality and overwintering can differ from the supplied constant-temperature/no-carryover assumptions.'),R('Host supply, competition, predation and disease can limit multiplication, so a constant threefold increase per generation is not an unlimited real-population forecast.'))],
 [('X degree days',(15-10)*120,600),('Y degree days',(16.5-10)*120,780),('Z complete generations',math.floor((18-10)*150/300),4),('relative multiplication',3**4/3**2,9)],'AHL increased insect life cycles. Degree-day rule fully supplied, incomplete cycles not rounded upward, and exponential growth limitations explicit.')

add('D4.3','Climate-related survival can change morph frequencies without revealing allele frequencies',
 'Two matched tawny-owl model cohorts each start with 100 brown and 300 gray individuals. In a snowy-winter treatment, survival is 0.40 for brown and 0.80 for gray; in a low-snow treatment it is 0.90 and 0.75. Assume no migration and equal reproduction after survival. Color has a heritable component, but the exact genetic architecture and dominance are not given. The values are constructed to explore a hypothesis about climate-related fitness.',bars(['Snowy brown','Snowy gray','Low-snow brown','Low-snow gray'],[40,240,90,225],'Expected survivors from matched starting cohorts','Constructed climate-related survival of owl color variants'),[
 P('Calculate the brown-morph frequency among survivors in each treatment and compare it with the initial frequency.',M('Initial frequency is 100/400 = 0.250; use each treatment’s surviving total as the new denominator.'),A('Snowy: 40/(40+240) = 0.1429; low-snow: 90/(90+225) = 0.2857 approximately.'),R('Brown frequency decreases under snowy conditions but increases under the specified low-snow relative-survival pattern.')),
 P('Explain what would be required for the survival difference to produce evolutionary change in the population.',R('The relevant color variation must be heritable and survivors must contribute differentially to subsequent generations.'),R('With these conditions and the stated absence of migration, altered relative fitness can change the inherited variant distribution over generations.')),
 P('Evaluate whether the brown-morph frequency can be inserted directly as q in a Hardy–Weinberg calculation.',R('A phenotype frequency is not automatically an allele frequency. Dominance, number of loci and genotype–phenotype relationships are not supplied.'),R('Additional inheritance/genotype information is required before using the morph proportion as an allele frequency or assigning a recessive q² interpretation.'))],
 [('initial brown fraction',100/400,.25),('snowy brown fraction',40/280,1/7),('low snow brown fraction',90/315,2/7)],'AHL climate-related selection using a named course example with explicitly invented model data. Morph and allele frequencies are not conflated; heritability versus plasticity is explicit.')

def save():
    assert len(QUESTIONS)==50
    assert Counter(q['level'] for q in QUESTIONS)=={'sl':20,'ahl':30}
    assert {q['syllabusCode'] for q in QUESTIONS}==set(TITLES)
    assert len({q['id'] for q in QUESTIONS})==50
    assert len({q['stem']+'\n'+str(q['parts']) for q in QUESTIONS})==50
    for q in QUESTIONS:
        assert q['marks']==sum(len(g['steps']) for g in q['markScheme'])
        assert not re.search(r'<(?:script|image|style|foreignObject)\b|\bhref\s*=',q['diagramSvg'],re.I)
        assert q['syllabusCode']!='D2.2' or q['level']=='ahl'
    path=ROOT/'content/ib/biology-2026-expansion/continuity-change.json';path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(json.dumps(QUESTIONS,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
    report={'status':'author-checked; separate review required','questions':50,'levels':{'sl':20,'ahl':30},'diagrams':50,'marks':sum(q['marks'] for q in QUESTIONS),'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'sourceGuide':'https://xmltwo.ibo.org/publications/EAD/2026_EN/GR4/GR4-Biology_EN.pdf','scope':'Current first-assessment-2025 guide with March2024 corrections; each AHL question requires an additional-HL statement. Shared D2.3 avoids numerical water potentials; D2.2 entirelyAHL.','provenance':'All wording, models, datasets and vector figures original; named organisms are course contexts, not attribution of invented measurements to published research.','records':RECORDS}
    out=ROOT/'docs/ib-2026-biology/continuity-change-author-review.json';out.parent.mkdir(parents=True,exist_ok=True);out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
    print(json.dumps({'questions':50,'figures':50,'checks':sum(len(r['checks']) for r in RECORDS),'sha256':report['sha256']}))
if __name__=='__main__':save()
